DROP TABLE IF EXISTS `milk_deliveries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `milk_deliveries` (
  `id` binary(16) NOT NULL,
  `member_id` binary(16) NOT NULL,
  `cow_id` binary(16) DEFAULT NULL COMMENT 'Optional ‚Äì which cow produced it',
  `quantity_litres` decimal(10,2) NOT NULL COMMENT 'Litres delivered',
  `price_per_litre_at_delivery` decimal(10,4) NOT NULL COMMENT 'Snapshot of active price ‚Äì never changes',
  `delivery_date` date NOT NULL COMMENT 'Used for duplicate delivery guard',
  `collected_at` timestamp NOT NULL COMMENT 'Exact date and time of delivery',
  `collection_officer_id` binary(16) DEFAULT NULL,
  `delivery_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RECORDED' COMMENT 'RECORDED | VERIFIED | DISPUTED',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `confirmed_by_member` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = member has confirmed this delivery is correct',
  `confirmed_at` timestamp NULL DEFAULT NULL COMMENT 'When the member confirmed',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_milk_deliveries_member_date_time` (`member_id`,`delivery_date`,`collected_at`),
  KEY `idx_milk_deliveries_member_id` (`member_id`),
  KEY `idx_milk_deliveries_cow_id` (`cow_id`),
  KEY `idx_milk_deliveries_delivery_date` (`delivery_date`),
  KEY `idx_milk_deliveries_collected_at` (`collected_at`),
  KEY `idx_milk_deliveries_officer_id` (`collection_officer_id`),
  KEY `idx_milk_deliveries_member_date_cover` (`member_id`,`delivery_date`,`quantity_litres`) COMMENT '''''''Covers monthly sum queries''''''',
  CONSTRAINT `fk_milk_deliveries_cow` FOREIGN KEY (`cow_id`) REFERENCES `cows` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_milk_deliveries_member` FOREIGN KEY (`member_id`) REFERENCES `members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_milk_deliveries_officer` FOREIGN KEY (`collection_officer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily milk deliveries; price snapshot ensures historical accuracy';
